INSERT INTO poc_quizzes (id, title, draw_count, pass_percent, max_attempts, cooldown_seconds, reward_xp) VALUES ('astronomia', 'Astronomia básica', 5, 70, NULL, 60, 100);
INSERT INTO poc_quiz_questions (quiz_id, kind, prompt, content, answer, rationale) VALUES
('astronomia', 'single', 'Qual é a estrela mais próxima da Terra?', '{"options": [{"id": "a", "text": "O Sol"}, {"id": "b", "text": "Próxima Centauri"}, {"id": "c", "text": "Sírius"}, {"id": "d", "text": "Betelgeuse"}]}', '{"option": "a"}', 'O Sol é uma estrela; Próxima Centauri é a mais próxima depois dele.'),
('astronomia', 'single', 'Qual planeta é conhecido como o planeta vermelho?', '{"options": [{"id": "a", "text": "Vênus"}, {"id": "b", "text": "Marte"}, {"id": "c", "text": "Júpiter"}, {"id": "d", "text": "Mercúrio"}]}', '{"option": "b"}', 'O óxido de ferro da superfície dá a Marte a cor avermelhada.'),
('astronomia', 'single', 'Qual é o maior planeta do Sistema Solar?', '{"options": [{"id": "a", "text": "Saturno"}, {"id": "b", "text": "Netuno"}, {"id": "c", "text": "Júpiter"}, {"id": "d", "text": "Terra"}]}', '{"option": "c"}', NULL),
('astronomia', 'single', 'Quanto tempo a luz do Sol leva, em média, para chegar à Terra?', '{"options": [{"id": "a", "text": "8 segundos"}, {"id": "b", "text": "8 minutos"}, {"id": "c", "text": "8 horas"}, {"id": "d", "text": "8 dias"}]}', '{"option": "b"}', 'A cerca de 150 milhões de km, a luz leva uns 8 minutos e 20 segundos.'),
('astronomia', 'single', 'O que causa as estações do ano na Terra?', '{"options": [{"id": "a", "text": "A distância até o Sol"}, {"id": "b", "text": "A inclinação do eixo da Terra"}, {"id": "c", "text": "As fases da Lua"}, {"id": "d", "text": "As manchas solares"}]}', '{"option": "b"}', 'O eixo inclinado faz cada hemisfério receber a luz do Sol mais de frente em uma parte do ano.'),
('astronomia', 'single', 'Como se chama a galáxia onde fica o Sistema Solar?', '{"options": [{"id": "a", "text": "Andrômeda"}, {"id": "b", "text": "Via Láctea"}, {"id": "c", "text": "Triângulo"}, {"id": "d", "text": "Grande Nuvem de Magalhães"}]}', '{"option": "b"}', NULL),
('astronomia', 'multiple', 'Quais destes são planetas rochosos?', '{"options": [{"id": "a", "text": "Mercúrio"}, {"id": "b", "text": "Terra"}, {"id": "c", "text": "Saturno"}, {"id": "d", "text": "Marte"}]}', '{"options": ["a", "b", "d"]}', 'Mercúrio, Vênus, Terra e Marte são rochosos; Saturno é um gigante gasoso.'),
('astronomia', 'multiple', 'Quais destes planetas têm anéis?', '{"options": [{"id": "a", "text": "Saturno"}, {"id": "b", "text": "Júpiter"}, {"id": "c", "text": "Marte"}, {"id": "d", "text": "Urano"}]}', '{"options": ["a", "b", "d"]}', 'Os quatro gigantes têm anéis; os de Saturno só são os mais visíveis.'),
('astronomia', 'multiple', 'Quais destes são satélites naturais?', '{"options": [{"id": "a", "text": "A Lua"}, {"id": "b", "text": "Europa"}, {"id": "c", "text": "Plutão"}, {"id": "d", "text": "Titã"}]}', '{"options": ["a", "b", "d"]}', 'Plutão é um planeta anão, não um satélite.'),
('astronomia', 'multiple', 'Quais destes fenômenos dependem da posição da Lua?', '{"options": [{"id": "a", "text": "As marés"}, {"id": "b", "text": "Os eclipses solares"}, {"id": "c", "text": "As estações do ano"}, {"id": "d", "text": "As fases da Lua"}]}', '{"options": ["a", "b", "d"]}', NULL),
('astronomia', 'truefalse', 'Plutão é classificado hoje como um planeta anão.', '{}', '{"value": true}', 'Desde 2006, a União Astronômica Internacional o classifica como planeta anão.'),
('astronomia', 'truefalse', 'A Lua tem luz própria.', '{}', '{"value": false}', 'A Lua reflete a luz do Sol; por isso tem fases.'),
('astronomia', 'truefalse', 'Vênus é o planeta mais quente do Sistema Solar.', '{}', '{"value": true}', 'A atmosfera densa de gás carbônico prende o calor, mesmo Mercúrio estando mais perto do Sol.'),
('astronomia', 'truefalse', 'Um ano-luz é uma medida de tempo.', '{}', '{"value": false}', 'É uma distância: o quanto a luz percorre em um ano.'),
('astronomia', 'cloze', 'Complete a frase sobre o Sol.', '{"text": "O Sol é uma {1} e a Terra é o {2} planeta a partir dele.", "blanks": {"1": ["estrela", "galáxia", "nebulosa"], "2": ["segundo", "terceiro", "quarto"]}}', '{"blanks": {"1": "estrela", "2": "terceiro"}}', 'O Sol é uma estrela anã amarela; a ordem é Mercúrio, Vênus e Terra.'),
('astronomia', 'cloze', 'Complete a frase sobre as fases da Lua.', '{"text": "Depois da lua nova vem a lua {1}, e depois da lua cheia vem a lua {2}.", "blanks": {"1": ["crescente", "minguante", "cheia"], "2": ["crescente", "minguante", "nova"]}}', '{"blanks": {"1": "crescente", "2": "minguante"}}', NULL),
('astronomia', 'cloze', 'Complete a frase sobre a gravidade.', '{"text": "Quanto maior a {1} de um corpo, maior a gravidade dele; e ela {2} com a distância.", "blanks": {"1": ["massa", "cor", "temperatura"], "2": ["diminui", "aumenta", "não muda"]}}', '{"blanks": {"1": "massa", "2": "diminui"}}', 'A gravidade cresce com a massa e cai com o quadrado da distância.'),
('astronomia', 'ordering', 'Ponha os planetas em ordem, do mais perto ao mais longe do Sol.', '{"items": [{"id": "me", "text": "Mercúrio"}, {"id": "ve", "text": "Vênus"}, {"id": "te", "text": "Terra"}, {"id": "ma", "text": "Marte"}]}', '{"order": ["me", "ve", "te", "ma"]}', NULL),
('astronomia', 'ordering', 'Ponha em ordem, do menor ao maior.', '{"items": [{"id": "lu", "text": "A Lua"}, {"id": "te", "text": "A Terra"}, {"id": "ju", "text": "Júpiter"}, {"id": "so", "text": "O Sol"}]}', '{"order": ["lu", "te", "ju", "so"]}', 'O Sol tem cerca de 10 vezes o diâmetro de Júpiter, que tem uns 11 da Terra.'),
('astronomia', 'ordering', 'Ponha as fases da Lua na ordem em que acontecem, começando pela nova.', '{"items": [{"id": "no", "text": "Nova"}, {"id": "cr", "text": "Crescente"}, {"id": "ch", "text": "Cheia"}, {"id": "mi", "text": "Minguante"}]}', '{"order": ["no", "cr", "ch", "mi"]}', NULL);
